// Generated by scripts/build-update.cjs. Edit scripts/sw-template.js instead.
const PREFIX = `tornet-app:${self.registration.scope}:`;
const CACHE = PREFIX + '__VERSION__';
const FILES = __FILES__;
const absolute = path => new URL(path,self.registration.scope).href;
const SHELL = new Set(FILES.map(absolute));
self.addEventListener('install',event=>{
 event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(FILES.map(file=>new Request(absolute(file),{cache:'reload'})))));
});
self.addEventListener('activate',event=>{
 event.waitUntil((async()=>{
  for(const key of await caches.keys())if(key.startsWith(PREFIX)&&key!==CACHE)await caches.delete(key);
  await self.clients.claim();
 })());
});
self.addEventListener('message',event=>{
 if(event.data?.type==='SKIP_WAITING')event.waitUntil(self.skipWaiting());
});
self.addEventListener('fetch',event=>{
 if(event.request.method!=='GET')return;
 const url=new URL(event.request.url);
 if(!url.href.startsWith(self.registration.scope))return;
 // Update checks must reach the server; never serve a cached worker script.
 if(url.pathname===new URL('sw.js',self.registration.scope).pathname)return;
 let target=url.origin+url.pathname;
 if(target===self.registration.scope)target=absolute('index.html');
 if(!SHELL.has(target))return;
 event.respondWith(caches.open(CACHE).then(async cache=>(await cache.match(target))||fetch(event.request)));
});
